const privacyPolicyVersion = process.env.PRIVACY_POLICY_VERSION || '2026-09-07';
const termsVersion = process.env.TERMS_VERSION || '2026-09-07';
const safetyNoticeVersion = process.env.SAFETY_NOTICE_VERSION || '2026-09-07';
