const alertRetentionDays = Math.max(30, Number(process.env.ALERT_RETENTION_DAYS || 30));
const heartbeatRetentionDays = Math.max(1, Number(process.env.HEARTBEAT_RETENTION_DAYS || 30));

// STRIPE SHOP
const stripeSecretKey = String(process.env.STRIPE_SECRET_KEY || '').trim();
const stripeWebhookSecret = String(process.env.STRIPE_WEBHOOK_SECRET || '').trim();
const stripePriceWallaaBox = String(process.env.STRIPE_PRICE_WALLAA_BOX || '').trim();
const stripePriceWallaaProMonthly = String(process.env.STRIPE_PRICE_WALLAA_PRO_MONTHLY || '').trim();
const stripeShippingCountries = String(process.env.STRIPE_SHIPPING_COUNTRIES || 'IT').split(',').map(x=>x.trim().toUpperCase()).filter(Boolean);
const shopBaseUrl = String(process.env.SHOP_BASE_URL || 'https://wallaasafety.com').replace(/\/$/,'');
const stripe = stripeSecretKey ? new Stripe(stripeSecretKey) : null;

// EMAIL
const emailEnabled = String(process.env.EMAIL_ENABLED ?? 'true').toLowerCase() === 'true';
const smtpHost = process.env.SMTP_HOST || '';
const smtpPort = Number(process.env.SMTP_PORT || 465);
const smtpSecure = String(process.env.SMTP_SECURE ?? String(smtpPort === 465)).toLowerCase() === 'true';
const smtpUser = process.env.SMTP_USER || '';
const smtpPass = process.env.SMTP_PASS || '';
const smtpFrom = process.env.SMTP_FROM || 'Wallaa Safety <safety@wallaasafety.com>';
const operatingCenterEnabled = String(process.env.OPERATING_CENTER_ENABLED ?? 'true').toLowerCase() === 'true';
const operatingCenterEmail = String(process.env.OPERATING_CENTER_EMAIL || 'safety@wallaasafety.com').trim().toLowerCase();
const operatingCenterName = String(process.env.OPERATING_CENTER_NAME || 'Wallaa Operating Center').trim();
const adminBootstrapEmail = String(process.env.ADMIN_BOOTSTRAP_EMAIL || 'admin@wallaasafety.com').trim().toLowerCase();
const adminBootstrapPassword = String(process.env.ADMIN_BOOTSTRAP_PASSWORD || '');
const adminSessionHours = Math.max(1, Math.min(72, Number(process.env.ADMIN_SESSION_HOURS || 12)));
const smtpConfigured = Boolean(emailEnabled && smtpHost && smtpPort && smtpUser && smtpPass);
const transporter = smtpConfigured ? nodemailer.createTransport({
  host: smtpHost,
  port: smtpPort,
  secure: smtpSecure,
  pool: true,
  maxConnections: 2,
  maxMessages: 50,
  auth: { user: smtpUser, pass: smtpPass },
  tls: { minVersion: 'TLSv1.2' }
}) : null;
const WALLAA_LOGO_PNG_BASE64 = '';
function wallaaLogoAttachment() {
  return { filename: 'wallaa-logo.png', content: Buffer.from(WALLAA_LOGO_PNG_BASE64, 'base64'), cid: 'wallaa-logo', contentType: 'image/png' };
}

// DATABASE (Rete Wallaa)
const databaseUrl = process.env.DATABASE_URL || '';
const pgSsl = String(process.env.PGSSL || 'false').toLowerCase() === 'true';
const dbConfigured = Boolean(databaseUrl);
const db = dbConfigured ? new Pool({
  connectionString: databaseUrl,
  ssl: pgSsl ? { rejectUnauthorized: false } : false,
  max: 8,
  idleTimeoutMillis: 30_000
}) : null;

// APNs (notifiche iPhone)
const apnsTeamId = process.env.APNS_TEAM_ID || '';
const apnsKeyId = process.env.APNS_KEY_ID || '';
const apnsBundleId = process.env.APNS_BUNDLE_ID || 'it.wallaa.safebutton';
const apnsPrivateKeyText = (process.env.APNS_PRIVATE_KEY || '').replace(/\\n/g, '\n');
const apnsConfigured = Boolean(apnsTeamId && apnsKeyId && apnsBundleId && apnsPrivateKeyText);
let apnsSigningKey = null;
let apnsJwt = null;
let apnsJwtCreatedAt = 0;

app.disable('x-powered-by');
app.use(helmet({ crossOriginResourcePolicy: false }));
app.use(cors({
  origin(origin, callback) {
    if (!origin || allowedOrigins.includes('*') || allowedOrigins.includes(origin)) return callback(null, true);
    callback(new Error('Origin non consentita'));
  }
}));
app.post('/api/shop/stripe/webhook', express.raw({ type:'application/json' }), async (req,res)=>{
  try {
    if (!stripe || !stripeWebhookSecret) return res.status(503).send('Stripe webhook non configurato');
    const sig = req.headers['stripe-signature'];
    const event = stripe.webhooks.constructEvent(req.body, sig, stripeWebhookSecret);
    await handleStripeEvent(event);
    res.json({ received:true });
  } catch (error) {
    console.error('Stripe webhook error:', error.message);
    res.status(400).send(`Webhook Error: ${error.message}`);
  }
});
app.use(express.json({ limit: '96kb' }));
app.use(rateLimit({ windowMs: 60_000, limit: 240, standardHeaders: 'draft-8', legacyHeaders: false }));
const authLimiter = rateLimit({ windowMs: 15 * 60_000, limit: 15, standardHeaders: 'draft-8', legacyHeaders: false });
const alertLimiter = rateLimit({ windowMs: 60_000, limit: 12, standardHeaders: 'draft-8', legacyHeaders: false });

app.get('/', (_req, res) => res.json({ ok: true, service: 'Wallaa Safe Button API', health: '/health' }));
