app.post('/api/system/test-email', async (req, res) => {
  try {
    const user = await requireNetworkUser(req);
    const email = clean(req.body?.email, 180).toLowerCase();
    const name = clean(req.body?.name, 120) || user.display_name || 'Utente Wallaa';
    if (!isEmail(email)) throw new Error('Email di test non valida.');
    if (user.email && email !== String(user.email).toLowerCase()) { const error = new Error('Il test email può essere inviato solo all’indirizzo del tuo account Wallaa.'); error.status = 403; throw error; }
    if (!emailEnabled) throw new Error('Invio email disattivato sul server.');
    if (!transporter) throw new Error('SMTP non configurato sul server.');

    const info = await transporter.sendMail({
      from: smtpFrom, to: email, subject: 'WALLAA — Test sistema email riuscito',
      html: buildTestEmailHtml({ name }),
      text: `WALLAA — Test sistema email riuscito\n\nCiao ${name}, il server Wallaa riesce a inviare email correttamente.`,
      attachments: [wallaaLogoAttachment()],
      headers: { 'X-Wallaa-Alert': 'system-test', 'X-Auto-Response-Suppress': 'OOF, AutoReply' }
    });
    res.json({ ok: true, email, messageId: info?.messageId || null });
  } catch (error) {
    res.status(error.status || 400).json({ error: error.message || 'Test email non riuscito.' });
  }
});

// --- ACCOUNT AUTHENTICATION -----------------------------------------------
app.post('/api/auth/register', authLimiter, async (req, res) => {
  try {
    requireDb();
    const installationId = clean(req.body?.installationId, 180);
    const profile = req.body?.profile || {};
    const firstName = clean(profile.firstName, 80);
    const lastName = clean(profile.lastName, 80);
    const email = clean(profile.email, 180).toLowerCase();
    const phone = clean(profile.phone, 50);
    const countryCode = clean(profile.countryCode, 12) || '+39';
    const language = clean(profile.language, 8) || 'en';
    const privacyAccepted = Boolean(profile.privacyAccepted);
    const termsAccepted = Boolean(profile.termsAccepted);
    const safetyNoticeAccepted = Boolean(profile.safetyNoticeAccepted);
    const acceptedPrivacyVersion = clean(profile.privacyPolicyVersion, 40) || privacyPolicyVersion;
    const acceptedTermsVersion = clean(profile.termsVersion, 40) || termsVersion;
    const acceptedSafetyNoticeVersion = clean(profile.safetyNoticeVersion, 40) || safetyNoticeVersion;
    const password = String(req.body?.password || '');
    const pushToken = clean(req.body?.pushToken, 512);
    const platform = clean(req.body?.platform, 30) || 'ios';
    if (!installationId) throw new Error('Installation ID mancante.');
    if (!firstName || !lastName || !isEmail(email) || !phone) throw new Error('Completa tutti i campi richiesti.');
    if (!privacyAccepted || !termsAccepted || !safetyNoticeAccepted) throw new Error('Informativa privacy, Termini e informativa sul trattamento dei dati di sicurezza devono essere confermati.');
    if (password.length < 8) throw new Error('La password deve contenere almeno 8 caratteri.');

    const duplicate = await db.query('SELECT * FROM wallaa_users WHERE LOWER(email)=LOWER($1) LIMIT 1', [email]);
    if (duplicate.rowCount) {
      const existing = duplicate.rows[0];
      if (existing.email_verification_required && !existing.email_verified_at) {
        let verificationEmailSent = true;
        try { await issueVerificationEmail(existing, req); }
        catch (mailError) {
          verificationEmailSent = false;
          console.error('Email verification resend after duplicate registration failed:', mailError.message);
        }
        return res.status(200).json({
          ok:true,
          pendingVerification:true,
          alreadyExists:true,
          email:existing.email,
          customerId:existing.customer_id,
          verificationRequired:true,
          verificationEmailSent
        });
      }
      const error = new Error('Esiste già un account Wallaa con questa email. Accedi invece di registrarti di nuovo.');
      error.status = 409;
      throw error;
    }

    const bootstrapToken = randomToken(32);
    const userId = crypto.randomUUID();
    const customerId = await createUniqueCustomerId();
    const qrToken = randomToken(18);
    const displayName = `${firstName} ${lastName}`.trim();
    const created = await db.query(`
      INSERT INTO wallaa_users (id, customer_id, installation_id, auth_token_hash, qr_token, display_name, first_name, last_name, email, phone, country_code, language, privacy_accepted_at, terms_accepted_at, safety_notice_accepted_at, privacy_policy_version, terms_version, safety_notice_version, password_hash, email_verification_required)
      VALUES ($1,$2,NULL,$3,$4,$5,$6,$7,$8,$9,$10,$11,NOW(),NOW(),NOW(),$12,$13,$14,$15,TRUE) RETURNING *
    `, [userId, customerId, hashToken(bootstrapToken), qrToken, displayName, firstName, lastName, email, phone, countryCode, language, acceptedPrivacyVersion, acceptedTermsVersion, acceptedSafetyNoticeVersion, passwordHash(password)]);
    const user = created.rows[0];
    let verificationEmailSent = true;
    try { await issueVerificationEmail(user, req); }
    catch (mailError) {
      verificationEmailSent = false;
      console.error('Initial verification email failed:', mailError.message);
    }
    res.status(201).json({ ok:true, pendingVerification:true, email:user.email, customerId:user.customer_id, verificationRequired:true, verificationEmailSent });
  } catch (error) {
    if (error?.code === '23505' || /duplicate key|unique constraint/i.test(String(error?.message || ''))) {
      console.error('Registration database conflict:', error.message);
      return res.status(409).json({ error: 'Non è stato possibile completare la registrazione. Riprova oppure accedi se hai già creato l’account.' });
    }
    res.status(error.status || 400).json({ error: error.message || 'Registrazione Wallaa non riuscita.' });
  }
});


app.post('/api/auth/resend-verification', authLimiter, async (req, res) => {
  try {
    requireDb();
    const email = clean(req.body?.email, 180).toLowerCase();
    if (!isEmail(email)) throw new Error('Inserisci un indirizzo email valido.');
    const result = await db.query('SELECT * FROM wallaa_users WHERE LOWER(email)=LOWER($1) LIMIT 1', [email]);
    const user = result.rows[0];
    // Generic response avoids exposing whether an address is registered.
    if (user?.email_verification_required && !user?.email_verified_at) await issueVerificationEmail(user, req);
    res.json({ ok:true, message:'Se l’account è in attesa di verifica, Wallaa ha inviato un nuovo link.' });
  } catch (error) { res.status(error.status || 400).json({ error:error.message || 'Invio email di verifica non riuscito.' }); }
});

app.get('/api/auth/verify-email', async (req, res) => {
  try {
    requireDb();
    const token = clean(req.query?.token, 512);
    if (!token) throw new Error('Link di verifica non valido.');
    const tokenHash = hashToken(token);
    const result = await db.query(`
      SELECT u.* FROM wallaa_email_verifications v
      JOIN wallaa_users u ON u.id=v.user_id
      WHERE v.token_hash=$1 AND v.expires_at > NOW()
      LIMIT 1
    `, [tokenHash]);
    const user = result.rows[0];
    if (!user) { const error = new Error('Il link di verifica non è valido o è scaduto. Richiedi una nuova email dall’app Wallaa.'); error.status=400; throw error; }
    await db.query('BEGIN');
    try {
      await db.query('UPDATE wallaa_users SET email_verified_at=NOW(),updated_at=NOW() WHERE id=$1', [user.id]);
      await db.query('DELETE FROM wallaa_email_verifications WHERE user_id=$1', [user.id]);
      await db.query('COMMIT');
    } catch (error) { await db.query('ROLLBACK'); throw error; }
    res.status(200).type('html').send(buildVerificationResultHtml({ ok:true, name:user.first_name || user.display_name || 'Wallaa' }));
  } catch (error) {
    res.status(error.status || 400).type('html').send(buildVerificationResultHtml({ ok:false, message:error.message || 'Verifica email non riuscita.' }));
  }
});

app.post('/api/auth/login', authLimiter, async (req, res) => {
  try {
    requireDb();
    const installationId = clean(req.body?.installationId, 180);
    const identifier = clean(req.body?.identifier ?? req.body?.email, 180);
    const normalizedIdentifier = identifier.toUpperCase().startsWith('WSB-') ? identifier.toUpperCase() : identifier.toLowerCase();
    const password = String(req.body?.password || '');
    const pushToken = clean(req.body?.pushToken, 512);
    const platform = clean(req.body?.platform, 30) || 'ios';
    if (!installationId || !identifier || !password) { const error = new Error('Email/ID cliente e password sono obbligatori.'); error.status = 400; throw error; }
    const result = await db.query(`
      SELECT * FROM wallaa_users
      WHERE LOWER(email)=LOWER($1) OR UPPER(customer_id)=UPPER($1)
      ORDER BY created_at ASC LIMIT 1
    `, [normalizedIdentifier]);
    const user = result.rows[0];
    if (!user?.password_hash || !passwordVerify(password, user.password_hash)) { const error = new Error('Email/ID cliente o password non corretti.'); error.status = 401; throw error; }
    if (String(user.account_status || 'enabled') === 'disabled') { const error = new Error('Account Wallaa disabilitato. Contatta l’assistenza.'); error.status = 403; throw error; }
    if (user.email_verification_required && !user.email_verified_at) { const error = new Error('Verifica prima il tuo indirizzo email tramite il link ricevuto da Wallaa.'); error.status = 403; throw error; }
    const authToken = randomToken(32);
    await storeInstallationToken(user.id, installationId, authToken, platform);
    if (pushToken) await upsertPushDevice(user.id, pushToken, platform);
    res.json(authResponse(user, installationId, authToken));
  } catch (error) { res.status(error.status || 400).json({ error: error.message || 'Accesso Wallaa non riuscito.' }); }
});

app.post('/api/auth/logout', async (req, res) => {
  try {
    const user = await requireNetworkUser(req);
    const installationId = clean(req.get('x-wallaa-installation-id'), 180);
    if (installationId) await db.query('DELETE FROM wallaa_installations WHERE installation_id=$1 AND user_id=$2', [installationId, user.id]);
    const supplied = req.get('x-wallaa-install-token') || '';
    if (installationId === user.installation_id && supplied && hashToken(supplied) === user.auth_token_hash) {
      await db.query('UPDATE wallaa_users SET auth_token_hash=$1,updated_at=NOW() WHERE id=$2', [hashToken(randomToken(32)), user.id]);
    }
    res.json({ ok: true });
  } catch (error) { res.status(error.status || 400).json({ error: error.message || 'Disconnessione non riuscita.' }); }
});

