// --- PERSONAL GUARDIANS (cloud-synced) -------------------------------------
app.get('/api/contacts', async (req, res) => {
  try {
    const user = await requireNetworkUser(req);
    const result = await db.query(`
      SELECT id,name,email,phone,role,sos_alerts,live_location,disconnect_alerts,created_at,updated_at
      FROM wallaa_contacts WHERE user_id=$1 ORDER BY CASE WHEN role='primary' THEN 0 ELSE 1 END, created_at ASC
    `, [user.id]);
    res.json({ ok:true, contacts:result.rows.map(mapPersonalContact), limit:contactLimitFor(user) });
  } catch (error) { res.status(error.status || 400).json({ error:error.message || 'Contatti Wallaa non disponibili.' }); }
});

app.post('/api/contacts/sync', async (req, res) => {
  const client = db ? await db.connect() : null;
  try {
    const user = await requireNetworkUser(req);
    const raw = Array.isArray(req.body?.contacts) ? req.body.contacts : [];
    const limit = contactLimitFor(user);
    if (raw.length > limit) { const error = new Error(`Il piano ${normalizedPlan(user)==='pro'?'Wallaa Pro':'Wallaa Basic'} consente massimo ${limit} contatti SOS.`); error.status=400; throw error; }
    const contacts = raw.map((entry, index) => ({
      id: clean(entry?.id,120) || crypto.randomUUID(),
      name: clean(entry?.name,120),
      email: clean(entry?.email,180).toLowerCase(),
      phone: clean(entry?.phone,50),
      role: entry?.role === 'primary' ? 'primary' : (entry?.role === 'guardian_pro' ? 'guardian_pro' : 'guardian'),
      sosAlerts: entry?.permissions?.sosAlerts !== false,
      liveLocation: entry?.permissions?.liveLocation !== false,
      disconnectAlerts: entry?.permissions?.disconnectAlerts !== false,
      index
    }));
    for (const c of contacts) {
      if (!c.name || !isEmail(c.email)) { const error = new Error('Nome ed email sono obbligatori per ogni Guardian.'); error.status=400; throw error; }
    }
    // Keep only one primary guardian.
    let primarySeen=false;
    for (const c of contacts) { if (c.role==='primary') { if (primarySeen) c.role='guardian'; else primarySeen=true; } }
    await client.query('BEGIN');
    await client.query('DELETE FROM wallaa_contacts WHERE user_id=$1', [user.id]);
    for (const c of contacts) {
      await client.query(`INSERT INTO wallaa_contacts (id,user_id,name,email,phone,role,sos_alerts,live_location,disconnect_alerts) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`, [c.id,user.id,c.name,c.email,c.phone,c.role,c.sosAlerts,c.liveLocation,c.disconnectAlerts]);
    }
    await client.query('COMMIT');
    const result = await db.query(`SELECT id,name,email,phone,role,sos_alerts,live_location,disconnect_alerts,created_at,updated_at FROM wallaa_contacts WHERE user_id=$1 ORDER BY CASE WHEN role='primary' THEN 0 ELSE 1 END, created_at ASC`, [user.id]);
    res.json({ ok:true, contacts:result.rows.map(mapPersonalContact), limit });
  } catch (error) {
    if (client) { try { await client.query('ROLLBACK'); } catch {} }
    res.status(error.status || 400).json({ error:error.message || 'Sincronizzazione Guardian non riuscita.' });
  } finally { client?.release?.(); }
});


