app.post('/api/network/register', async (req, res) => {
  try {
    const user = await requireNetworkUser(req);
    const displayName = clean(req.body?.displayName, 80) || user.display_name || 'Utente Wallaa';
    const pushToken = clean(req.body?.pushToken, 512);
    const platform = clean(req.body?.platform, 30) || 'ios';
    const profile = req.body?.profile || {};
    const firstName = clean(profile.firstName, 80);
    const lastName = clean(profile.lastName, 80);
    const email = clean(profile.email, 180).toLowerCase();
    const phone = clean(profile.phone, 50);
    const countryCode = clean(profile.countryCode, 12) || '+39';
    const language = clean(profile.language, 8) || user.language || 'en';
    const liveProtectionEnabled = profile.liveProtectionEnabled == null ? Boolean(user.live_protection_enabled) : Boolean(profile.liveProtectionEnabled);
    if (email && !isEmail(email)) throw new Error('Email non valida.');
    if (email && user.email && email !== String(user.email).toLowerCase()) {
      const duplicate = await db.query('SELECT id FROM wallaa_users WHERE LOWER(email)=LOWER($1) AND id<>$2 LIMIT 1', [email, user.id]);
      if (duplicate.rowCount) { const error = new Error('Questa email è già associata a un altro account Wallaa.'); error.status = 409; throw error; }
    }
    const updated = await db.query(`
      UPDATE wallaa_users SET display_name=$1,
        first_name=COALESCE(NULLIF($2,''),first_name), last_name=COALESCE(NULLIF($3,''),last_name),
        email=COALESCE(NULLIF($4,''),email), phone=COALESCE(NULLIF($5,''),phone), country_code=COALESCE(NULLIF($6,''),country_code), language=$7,
        live_protection_enabled=$8, live_protection_enabled_at=CASE WHEN $8::boolean THEN COALESCE(live_protection_enabled_at,NOW()) ELSE NULL END,
        updated_at=NOW() WHERE id=$9 RETURNING *
    `, [displayName, firstName, lastName, email, phone, countryCode, language, liveProtectionEnabled, user.id]);
    const nextUser = updated.rows[0];
    const installationId = clean(req.get('x-wallaa-installation-id'), 180);
    const supplied = req.get('x-wallaa-install-token') || '';
    if (installationId && supplied) await storeInstallationToken(nextUser.id, installationId, supplied, platform);
    if (pushToken) await upsertPushDevice(nextUser.id, pushToken, platform);
    res.json({ ok:true, userId:nextUser.id, qrToken:nextUser.qr_token, qrPayload:qrPayload(nextUser.qr_token), displayName:nextUser.display_name, profile:publicProfile(nextUser) });
  } catch (error) { res.status(error.status || 400).json({ error:error.message || 'Sincronizzazione Wallaa non riuscita.' }); }
});

