app.delete('/api/account', async (req, res) => {
  try {
    const user = await requireNetworkUser(req);
    await db.query('DELETE FROM wallaa_users WHERE id=$1', [user.id]);
    res.json({ ok:true });
  } catch (error) { res.status(error.status || 400).json({ error:error.message || 'Cancellazione account non riuscita.' }); }
});

async function handleDeviceHeartbeat(req, res) {
  try {
    const user = await requireNetworkUser(req);
    const deviceId = clean(req.body?.deviceId, 180);
    const status = clean(req.body?.status, 30).toLowerCase();
    const allowed = new Set(['connected', 'weak', 'disconnected', 'searching']);
    if (!deviceId) throw new Error('Device ID mancante.');
    if (!allowed.has(status)) throw new Error('Stato dispositivo non valido.');

    const batteryValue = req.body?.battery == null ? null : Number(req.body.battery);
    const rssiValue = req.body?.rssi == null ? null : Number(req.body.rssi);
    const battery = Number.isFinite(batteryValue) ? Math.max(0, Math.min(100, Math.round(batteryValue))) : null;
    const rssi = Number.isFinite(rssiValue) ? Math.round(rssiValue) : null;
    const lastSeenAt = clean(req.body?.lastSeenAt, 80) || null;
    const notifyGuardians = Boolean(req.body?.notifyGuardians) && status === 'disconnected';

    await db.query(`
      INSERT INTO wallaa_devices (id,user_id,device_identifier,name,connection_status,battery,rssi,last_seen_at)
      VALUES ($1,$2,$3,'Wallaa Button',$4,$5,$6,$7)
      ON CONFLICT (user_id,device_identifier)
      DO UPDATE SET connection_status=EXCLUDED.connection_status,battery=EXCLUDED.battery,rssi=EXCLUDED.rssi,last_seen_at=EXCLUDED.last_seen_at,updated_at=NOW()
    `, [crypto.randomUUID(), user.id, deviceId, status, battery, rssi, lastSeenAt]);

    await db.query(`
      INSERT INTO wallaa_device_heartbeats (id,user_id,device_id,status,battery,rssi,last_seen_at,created_at)
      VALUES ($1,$2,$3,$4,$5,$6,$7,NOW())
    `, [crypto.randomUUID(), user.id, deviceId, status, battery, rssi, lastSeenAt]);

    const delivered = [];
    const failed = [];
    const pushDelivered = [];
    const pushFailed = [];

    if (notifyGuardians) {
      const rawContacts = Array.isArray(req.body?.contacts) ? req.body.contacts.slice(0, maxContacts) : [];
      const emailContacts = rawContacts.map((contact) => ({
        name: clean(contact?.name, 80) || 'Contatto',
        email: clean(contact?.email, 180).toLowerCase(),
        phone: clean(contact?.phone, 40)
      })).filter((contact) => isEmail(contact.email));

      if (emailContacts.length && (!emailEnabled || !transporter)) {
        for (const contact of emailContacts) failed.push({ name: contact.name, email: contact.email, error: 'SMTP non configurato sul server.' });
      }
      if (emailEnabled && transporter) {
        for (const contact of emailContacts) {
          try {
            const info = await transporter.sendMail({
              from: smtpFrom,
              to: contact.email,
              subject: '⚠️ WALLAA CONNECTION GUARD — Safe Button disconnected',
              html: buildDisconnectHtml({ user, contact, battery, lastSeenAt }),
              text: buildDisconnectText({ user, contact, battery, lastSeenAt }),
              headers: { 'X-Wallaa-Alert': 'connection-guard', 'X-Auto-Response-Suppress': 'OOF, AutoReply' }
            });
            delivered.push({ name: contact.name, email: contact.email, system: contact.role === 'system_center', messageId: info?.messageId || null });
          } catch (error) {
            failed.push({ name: contact.name, email: contact.email, error: error.message || 'Invio fallito' });
          }
        }
      }

      const devices = await db.query(`
        SELECT d.push_token,d.platform
        FROM wallaa_links l
        JOIN wallaa_push_devices d ON d.user_id=l.guardian_user_id AND d.enabled=TRUE
        WHERE l.protected_user_id=$1 AND l.disconnect_alerts=TRUE
      `, [user.id]);

      for (const row of devices.rows) {
        if (row.platform !== 'ios') { pushFailed.push({ platform: row.platform, error: 'Push Android non ancora configurata.' }); continue; }
        if (!apnsConfigured) { pushFailed.push({ platform: 'ios', error: 'APNs non configurato.' }); continue; }
        try {
          await sendApnsStatus(row.push_token, { title: 'Wallaa Connection Guard', body: 'Wallaa Button risulta disconnesso.', type: 'wallaa_disconnect' });
          pushDelivered.push({ platform: 'ios' });
        } catch (error) {
          pushFailed.push({ platform: 'ios', error: error.message || 'Push fallita' });
        }
      }
    }

    res.json({ ok:true, status, delivered, failed, pushDelivered, pushFailed });
  } catch (error) {
    res.status(error.status || 400).json({ error:error.message || 'Heartbeat dispositivo non riuscito.' });
  }
}



// --- WALLAA ADMIN / OPERATING CONSOLE -------------------------------------
async function bootstrapAdmin() {
  if (!db) return;
  if (!adminBootstrapPassword) {
    console.warn(`ADMIN_BOOTSTRAP_PASSWORD non configurata: account ${adminBootstrapEmail} non creato/aggiornato.`);
    return;
  }
  if (adminBootstrapPassword.length < 12) {
    console.warn('ADMIN_BOOTSTRAP_PASSWORD deve avere almeno 12 caratteri.');
    return;
  }

  const passwordHashValue = passwordHash(adminBootstrapPassword);
  const existing = await db.query(
    'SELECT id,email,enabled FROM wallaa_admin_users WHERE LOWER(email)=LOWER($1) LIMIT 1',
    [adminBootstrapEmail]
  );

  if (!existing.rowCount) {
    await db.query(
      'INSERT INTO wallaa_admin_users (id,email,password_hash,role,enabled) VALUES ($1,$2,$3,$4,TRUE)',
      [crypto.randomUUID(), adminBootstrapEmail, passwordHashValue, 'admin']
    );
    console.log(`✓ Admin Wallaa creato: ${adminBootstrapEmail}`);
    return;
  }

  // The Render bootstrap password is the authoritative recovery credential.
  // Keeping the hash in sync removes the need for manual SQL if the password is rotated.
  await db.query(
    `UPDATE wallaa_admin_users
     SET password_hash=$1, role='admin', enabled=TRUE, updated_at=NOW()
     WHERE id=$2`,
    [passwordHashValue, existing.rows[0].id]
  );
  await db.query('DELETE FROM wallaa_admin_sessions WHERE admin_id=$1', [existing.rows[0].id]);
  console.log(`✓ Admin Wallaa sincronizzato: ${adminBootstrapEmail}`);
}
async function requireAdmin(req) {
  requireDb();
  const raw = String(req.get('authorization') || '');
  const token = raw.toLowerCase().startsWith('bearer ') ? raw.slice(7).trim() : '';
  if (!token) { const e=new Error('Sessione amministratore mancante.'); e.status=401; throw e; }
  const result = await db.query(`SELECT a.* FROM wallaa_admin_sessions s JOIN wallaa_admin_users a ON a.id=s.admin_id WHERE s.token_hash=$1 AND s.expires_at>NOW() AND a.enabled=TRUE LIMIT 1`,[hashToken(token)]);
  const admin=result.rows[0];
  if(!admin){const e=new Error('Sessione amministratore non autorizzata o scaduta.');e.status=401;throw e;}
  db.query('UPDATE wallaa_admin_sessions SET last_seen_at=NOW() WHERE token_hash=$1',[hashToken(token)]).catch(()=>{});
  return admin;
}
async function adminAudit(admin,req,action,targetType='',targetId='',details={}) {
  try { await db.query('INSERT INTO wallaa_admin_audit (id,admin_id,action,target_type,target_id,details,ip) VALUES ($1,$2,$3,$4,$5,$6,$7)',[crypto.randomUUID(),admin?.id||null,action,targetType,targetId?String(targetId):null,JSON.stringify(details||{}),clean(req.ip,100)]); } catch(error){ console.warn('Admin audit failed:',error.message); }
}
