function requireAppKey(req, res, next) {
  if (appKey && (req.get('x-wallaa-safe-key') || req.get('x-legacy-app-key')) !== appKey) {
    return res.status(401).json({ error: 'API key non valida.' });
  }
  next();
}

function requireDb() {
  if (!db) { const error = new Error('Database Rete Wallaa non configurato.'); error.status = 503; throw error; }
}

function shopProductFromStripe(code,fallbackName,price,kind){
  const product=price?.product && typeof price.product==='object' ? price.product : null;
  return {code,name:product?.name||fallbackName,description:product?.description||'',configured:true,amount:price?.unit_amount??null,currency:price?.currency||'eur',interval:price?.recurring?.interval||null,kind};
}
function stripeId(value){return typeof value==='string'?value:(value?.id||null);}
async function handleStripeEvent(event){
  if(!db) return;
  const obj=event.data?.object||{};
  if(event.type==='checkout.session.completed' || event.type==='checkout.session.async_payment_succeeded'){
    const code=obj.metadata?.wallaa_product||'';
    if(code==='pro'){
      const userId=obj.metadata?.wallaa_user_id||obj.client_reference_id;
      if(userId) await db.query(`UPDATE wallaa_users SET subscription_tier='pro',stripe_customer_id=$1,stripe_subscription_id=$2,stripe_subscription_status='active',updated_at=NOW() WHERE id=$3`,[stripeId(obj.customer),stripeId(obj.subscription),userId]);
    }
    if(code==='box'){
      const shipping=obj.shipping_details||obj.collected_information?.shipping_details||null;
      const orderId=`WAL-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${crypto.randomBytes(3).toString('hex').toUpperCase()}`;
      await db.query(`INSERT INTO wallaa_orders (stripe_session_id,order_id,product_code,status,email,customer_name,phone,amount_total,currency,shipping,stripe_payment_intent_id) VALUES ($1,$2,'box',$3,$4,$5,$6,$7,$8,$9,$10) ON CONFLICT (stripe_session_id) DO NOTHING`,[obj.id,orderId,obj.payment_status||'paid',obj.customer_details?.email||null,obj.customer_details?.name||null,obj.customer_details?.phone||null,obj.amount_total||null,obj.currency||null,shipping?JSON.stringify(shipping):null,stripeId(obj.payment_intent)]);
    }
  }
  if(event.type==='customer.subscription.updated' || event.type==='customer.subscription.deleted'){
    const userId=obj.metadata?.wallaa_user_id;
    if(userId){
      const active=['active','trialing'].includes(obj.status);
      await db.query(`UPDATE wallaa_users SET subscription_tier=$1,stripe_customer_id=COALESCE($2,stripe_customer_id),stripe_subscription_id=$3,stripe_subscription_status=$4,updated_at=NOW() WHERE id=$5`,[active?'pro':'basic',stripeId(obj.customer),obj.id,obj.status||event.type,userId]);
    }
  }
}

async function requireNetworkUser(req) {
  requireDb();
  const installationId = clean(req.get('x-wallaa-installation-id'), 180);
  const token = req.get('x-wallaa-install-token') || '';
  if (!installationId || !token) { const error = new Error('Sessione Wallaa mancante. Accedi nuovamente.'); error.status = 401; throw error; }
  const tokenHash = hashToken(token);
  const installation = await db.query(`
    SELECT u.* FROM wallaa_installations i JOIN wallaa_users u ON u.id=i.user_id
    WHERE i.installation_id=$1 AND i.auth_token_hash=$2 LIMIT 1
  `, [installationId, tokenHash]);
  if (installation.rowCount) {
    if (String(installation.rows[0].account_status || 'enabled') === 'disabled') { const error = new Error('Account Wallaa disabilitato.'); error.status = 403; throw error; }
    db.query('UPDATE wallaa_installations SET last_seen_at=NOW(),updated_at=NOW() WHERE installation_id=$1', [installationId]).catch(() => {});
    return installation.rows[0];
  }
  // One-time compatibility path for accounts created by v4.0.4 and earlier.
  const legacy = await db.query('SELECT * FROM wallaa_users WHERE installation_id=$1', [installationId]);
  if (legacy.rowCount && tokenHash === legacy.rows[0].auth_token_hash) {
    if (String(legacy.rows[0].account_status || 'enabled') === 'disabled') { const error = new Error('Account Wallaa disabilitato.'); error.status = 403; throw error; }
    await storeInstallationToken(legacy.rows[0].id, installationId, token, 'ios');
    return legacy.rows[0];
  }
  const error = new Error('Sessione Wallaa non autorizzata. Accedi nuovamente.'); error.status = 401; throw error;
}

function validatePayload(body) {
  const userName = clean(body?.userName, 80) || 'Utente Wallaa Safe Button';
  const userPhone = clean(body?.userPhone, 50);
  const safetyWord = clean(body?.safetyWord, 32);
  const language = normalizeEmailLanguage(body?.language);
  const trigger = clean(body?.trigger, 40) || 'unknown';
  const eventPacketIdRaw = Number(body?.eventPacketId);
  const eventPacketId = Number.isInteger(eventPacketIdRaw) && eventPacketIdRaw >= 0 && eventPacketIdRaw <= 255 ? eventPacketIdRaw : null;
  const contacts = Array.isArray(body?.contacts) ? body.contacts.slice(0, maxContacts) : [];
  const location = body?.location ? validateLocation(body.location) : null;

  const validContacts = contacts.map((c) => ({
    name: clean(c?.name, 80) || 'Contatto',
    email: clean(c?.email, 180).toLowerCase(),
    phone: clean(c?.phone, 40),
    role: clean(c?.role, 30) || 'guardian',
    permissions: {
      sosAlerts: c?.permissions?.sosAlerts !== false,
      liveLocation: c?.permissions?.liveLocation !== false,
      disconnectAlerts: c?.permissions?.disconnectAlerts !== false
    }
  })).filter((c) => isEmail(c.email) && c.permissions.sosAlerts);

  return {
    userName,
    userPhone,
    safetyWord,
    language,
    trigger,
    eventPacketId,
    device: body?.device ? { name: clean(body.device.name, 100), id: clean(body.device.id, 180) } : null,
    contacts: validContacts,
    location
  };
}

function validateLocation(location) {
  const latitude = Number(location.latitude);
  const longitude = Number(location.longitude);
  const accuracy = location.accuracy == null ? null : Number(location.accuracy);
  if (!Number.isFinite(latitude) || latitude < -90 || latitude > 90) throw new Error('Latitudine non valida.');
  if (!Number.isFinite(longitude) || longitude < -180 || longitude > 180) throw new Error('Longitudine non valida.');
  return {
    latitude,
    longitude,
    accuracy: Number.isFinite(accuracy) ? Math.round(accuracy) : null,
    capturedAt: clean(location.capturedAt, 80) || new Date().toISOString(),
    mapsUrl: `https://www.google.com/maps?q=${encodeURIComponent(`${latitude},${longitude}`)}`
  };
}

async function sendApns(deviceToken, alert) {
  const jwt = await getApnsJwt();
  const client = http2.connect('https://api.push.apple.com');
  const locationAllowed = alert.locationShared !== false;
  const hasLocation = locationAllowed && Number.isFinite(Number(alert.latitude)) && Number.isFinite(Number(alert.longitude));
  const body = JSON.stringify({
    aps: {
      alert: {
        title: `🚨 SOS da ${alert.userName}`,
        body: hasLocation ? 'Ha attivato Wallaa Safe Button. Tocca per aprire subito la posizione.' : (locationAllowed && alert.liveUrl ? 'Ha attivato Wallaa Safe Button. Apri la posizione live: il GPS si aggiorna appena disponibile.' : "Ha attivato Wallaa Safe Button. Apri Wallaa per verificare l'emergenza.")
      },
      sound: 'wallaa-guardian-siren.wav',
      badge: 1,
      'interruption-level': 'time-sensitive'
    },
    type: 'wallaa_sos',
    alertId: alert.alertId,
    userName: alert.userName,
    userPhone: alert.userPhone || '',
    trigger: alert.trigger,
    locationShared: locationAllowed ? '1' : '0',
    locationAvailable: hasLocation ? '1' : '0',
    ...(locationAllowed && alert.liveUrl ? { liveUrl: alert.liveUrl } : {}),
    ...(hasLocation ? {
      latitude: String(alert.latitude),
      longitude: String(alert.longitude),
      accuracy: alert.accuracy == null ? '' : String(alert.accuracy),
      mapsUrl: alert.mapsUrl
    } : {}),
    createdAt: alert.createdAt
  });

  return new Promise((resolve, reject) => {
    const request = client.request({
      ':method': 'POST',
      ':path': `/3/device/${deviceToken}`,
      'authorization': `bearer ${jwt}`,
      'apns-topic': apnsBundleId,
      'apns-push-type': 'alert',
      'apns-priority': '10',
      'content-type': 'application/json'
    });
    let status = 0;
    let responseBody = '';
    request.setEncoding('utf8');
    request.on('response', (headers) => { status = Number(headers[':status'] || 0); });
    request.on('data', (chunk) => { responseBody += chunk; });
    request.on('end', () => {
      client.close();
      if (status === 200) return resolve(true);
      let reason = `APNs ${status}`;
      try { reason = JSON.parse(responseBody)?.reason || reason; } catch { /* noop */ }
      reject(new Error(reason));
    });
    request.on('error', (error) => { client.close(); reject(error); });
    request.end(body);
  });
}


async function sendApnsStatus(deviceToken, statusPayload) {
  const jwt = await getApnsJwt();
  const client = http2.connect('https://api.push.apple.com');
  const body = JSON.stringify({
    aps: {
      alert: { title: statusPayload.title, body: statusPayload.body },
      sound: 'default',
      badge: statusPayload.type === 'wallaa_safe' ? 0 : 1,
      'interruption-level': 'time-sensitive'
    },
    type: statusPayload.type || 'wallaa_status',
    alertId: statusPayload.alertId || ''
  });
  return new Promise((resolve, reject) => {
    const request = client.request({
      ':method': 'POST', ':path': `/3/device/${deviceToken}`,
      'authorization': `bearer ${jwt}`, 'apns-topic': apnsBundleId,
      'apns-push-type': 'alert', 'apns-priority': '10', 'content-type': 'application/json'
    });
    let status = 0; let responseBody = '';
    request.setEncoding('utf8');
    request.on('response', (headers) => { status = Number(headers[':status'] || 0); });
    request.on('data', (chunk) => { responseBody += chunk; });
    request.on('end', () => {
      client.close();
      if (status === 200) return resolve(true);
      let reason = `APNs ${status}`;
      try { reason = JSON.parse(responseBody)?.reason || reason; } catch { /* noop */ }
      reject(new Error(reason));
    });
    request.on('error', (error) => { client.close(); reject(error); });
    request.end(body);
  });
}

async function getApnsJwt() {
  const now = Math.floor(Date.now() / 1000);
  if (apnsJwt && now - apnsJwtCreatedAt < 45 * 60) return apnsJwt;
  if (!apnsSigningKey) apnsSigningKey = await importPKCS8(apnsPrivateKeyText, 'ES256');
  apnsJwt = await new SignJWT({}).setProtectedHeader({ alg: 'ES256', kid: apnsKeyId }).setIssuer(apnsTeamId).setIssuedAt(now).sign(apnsSigningKey);
  apnsJwtCreatedAt = now;
  return apnsJwt;
}

function randomToken(bytes) { return crypto.randomBytes(bytes).toString('base64url'); }
function hashToken(value) { return crypto.createHash('sha256').update(String(value)).digest('hex'); }
function passwordHash(value) { const salt = crypto.randomBytes(16); const hash = crypto.scryptSync(String(value), salt, 64); return `${salt.toString('hex')}:${hash.toString('hex')}`; }
function passwordVerify(value, stored) {
  try {
    const [saltHex, hashHex] = String(stored || '').split(':');
    if (!saltHex || !hashHex) return false;
    const expected = Buffer.from(hashHex, 'hex');
    const actual = crypto.scryptSync(String(value), Buffer.from(saltHex, 'hex'), expected.length);
    return expected.length === actual.length && crypto.timingSafeEqual(expected, actual);
  } catch { return false; }
}

const CUSTOMER_ID_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
function makeCustomerId() {
  let suffix = '';
  for (let i = 0; i < 6; i += 1) suffix += CUSTOMER_ID_ALPHABET[crypto.randomInt(0, CUSTOMER_ID_ALPHABET.length)];
  return `WSB-${suffix}`;
}
async function createUniqueCustomerId() {
  requireDb();
  for (let attempt = 0; attempt < 20; attempt += 1) {
    const candidate = makeCustomerId();
    const exists = await db.query('SELECT 1 FROM wallaa_users WHERE customer_id=$1 LIMIT 1', [candidate]);
    if (!exists.rowCount) return candidate;
  }
  throw new Error('Impossibile generare un ID cliente univoco. Riprova.');
}
async function backfillCustomerIds() {
  if (!db) return;
  const missing = await db.query("SELECT id FROM wallaa_users WHERE customer_id IS NULL OR customer_id='' ORDER BY created_at ASC");
  for (const row of missing.rows) {
    const customerId = await createUniqueCustomerId();
    await db.query('UPDATE wallaa_users SET customer_id=$1,updated_at=NOW() WHERE id=$2', [customerId, row.id]);
  }
}

function normalizePlanValue(value) {
  const normalized = String(value || '').trim().toLowerCase().replace(/[\s_-]+/g,'');
  if (['pro','wallaapro'].includes(normalized)) return 'pro';
  if (['basic','wallaabasic'].includes(normalized)) return 'basic';
  return null;
}
function normalizedPlan(user) {
  return normalizePlanValue(user?.subscription_tier) || 'basic';
}
function contactLimitFor(user) { return normalizedPlan(user) === 'pro' ? 5 : 2; }

function publicProfile(user) {
  return {
    customerId:user.customer_id || '', firstName:user.first_name || '', lastName:user.last_name || '', email:user.email || '', phone:user.phone || '',
    countryCode:user.country_code || '+39', language:user.language || 'en', plan:normalizedPlan(user), accountStatus:user.account_status || 'enabled', liveProtectionEnabled:Boolean(user.live_protection_enabled), emailVerified:!user.email_verification_required || Boolean(user.email_verified_at), privacyAccepted:Boolean(user.privacy_accepted_at), termsAccepted:Boolean(user.terms_accepted_at), safetyNoticeAccepted:Boolean(user.safety_notice_accepted_at), privacyPolicyVersion:user.privacy_policy_version || '', termsVersion:user.terms_version || '', safetyNoticeVersion:user.safety_notice_version || '',
    onboardingComplete:true
  };
}
function authResponse(user, installationId, authToken, language = '') {
  const profile = publicProfile(user);
  if (language) profile.language = language;
  return { ok:true, userId:user.id, installationId, authToken, qrToken:user.qr_token, qrPayload:qrPayload(user.qr_token), displayName:user.display_name, profile };
}
async function storeInstallationToken(userId, installationId, token, platform = 'ios') {
  if (!installationId || !token) return;
  await db.query(`
    INSERT INTO wallaa_installations (id,user_id,installation_id,auth_token_hash,platform,last_seen_at)
    VALUES ($1,$2,$3,$4,$5,NOW())
    ON CONFLICT (installation_id) DO UPDATE SET user_id=EXCLUDED.user_id,auth_token_hash=EXCLUDED.auth_token_hash,platform=EXCLUDED.platform,updated_at=NOW(),last_seen_at=NOW()
  `, [crypto.randomUUID(), userId, installationId, hashToken(token), platform]);
}

function qrPayload(token) { return `WALLAA:PAIR:${token}`; }
function extractQrToken(value) {
  const text = clean(value, 300);
  if (text.startsWith('WALLAA:PAIR:')) return text.slice('WALLAA:PAIR:'.length);
  return '';
}
function isInvalidApnsTokenError(reason) {
  return ['BadDeviceToken', 'Unregistered', 'DeviceTokenNotForTopic'].includes(String(reason || '').trim());
}

function mapPersonalContact(row) { return { id:row.id, name:row.name || '', email:row.email || '', phone:row.phone || '', role:row.role === 'primary' ? 'primary' : 'guardian', permissions:{ sosAlerts:row.sos_alerts !== false, liveLocation:row.live_location !== false, disconnectAlerts:row.disconnect_alerts !== false }, createdAt:row.created_at, updatedAt:row.updated_at }; }
function mapLink(row) { return { linkId: row.link_id, userId: row.user_id, displayName: row.display_name, role: row.role || 'guardian', permissions: { sosAlerts: row.sos_alerts !== false, liveLocation: row.live_location !== false, disconnectAlerts: row.disconnect_alerts !== false }, createdAt: row.created_at }; }
function mapAlert(row) {
  return { id: row.id, ownerName: row.user_name, trigger: row.trigger, at: row.captured_at, location: { latitude: row.latitude, longitude: row.longitude, accuracy: row.accuracy, mapsUrl: row.maps_url } };
}

